import heapq

def match(orders):
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq'}
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if top_id not in book or book[top_id]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                trade_qty = min(remaining, book[top_id]['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                book[top_id]['qty'] -= trade_qty
                if book[top_id]['qty'] == 0:
                    del book[top_id]
                    heapq.heappop(sell_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                top_neg_price, top_seq, top_id = buy_heap[0]
                top_price = -top_neg_price
                if top_id not in book or book[top_id]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                trade_qty = min(remaining, book[top_id]['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                book[top_id]['qty'] -= trade_qty
                if book[top_id]['qty'] == 0:
                    del book[top_id]
                    heapq.heappop(buy_heap)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

